tk.sm.state("firstStateName", "Summarize active project status", async (ctx, tk, input) => {
  try {
    const projectStatus = await tk.services.dynamic_service_1({});
    tk.sm.memory.projectStatus = projectStatus;
    return "finalStateName";
  } catch (error) {
    tk.log("Failed to summarize project status", "error");
    return "errorStateName";
  }
}, {
  "finalStateName": null,
  "errorStateName": null
});

return await tk.sm.run("firstStateName", {}, ctx, tk);
